import{z as s,x as p,o as r,c as A,q as t,j as o,D as e,d as i,s as l,S as B,b as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Zernike 像差","description":"","frontmatter":{"title":"Zernike 像差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/zernike-aberrations.md","filePath":"litho/zernike-aberrations.md","lastUpdated":1791063341000}'),h={name:"litho/zernike-aberrations.md"};function d(c,a,m,k,D,C){const E=p("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="zernike-像差" tabindex="-1">Zernike 像差 <a class="header-anchor" href="#zernike-像差" aria-label="Permalink to &quot;Zernike 像差&quot;">​</a></h1><div class="epigraph"><p>光瞳里残留的相位不是一团雾；在圆域上它可以按 Zernike 多项式展开，每一项对应一种可测量、可补偿的波前形状。</p><footer>—— Zernike 圆域正交多项式；光学车间与镜头计量的用法见 Malacara, Optical Shop Testing</footer></div><p><a href="/litho/jones-polarization">上一课</a>（Jones 矩阵）。把矢量通道的对比差钉死，光瞳仍被当成「除几何 s/p 与离焦外相位理想」。缺口是：真实投影物镜的波前有加工、装调与热漂移残差，必须在单位圆上展开。本课把光瞳相位写成 Zernike 系数；有限带宽如何把这些项按波长搅在一起，留给<a href="/litho/chromatic-bandwidth">色差与光源带宽</a>。不要从瑞利 CD 重讲，也不要引用未公开的某代镜头 Zernike 预算表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TCC 里的 \\(P(\\mathbf{f})\\) 是复透过率。振幅近乎硬切之后，剩下的信息主要是相位 \\(W(\\rho,\\phi)\\)。不展开，\\(W\\) 只是一张图，无法说「彗差还是像散在吃套刻」。Zernike 多项式 \\(\\{Z_j\\}\\) 在圆域上正交，把</p> \\[W(\\rho,\\phi)=\\sum_j c_j Z_j(\\rho,\\phi) \\]<p>收成一列系数。缺口因此是光瞳相位的基底，而不是再选一次 TE/TM。</p><p><span class="marginnote">直觉类比：Zernike 展开之于波前，就像分解和弦之于一段声音——任何复杂形状都能拆成一组「标准形状」的加权和，每一项有名字（像散、彗差……）、有系数（占多少）、可单独测量与补偿。有了这列系数，镜头质量才能写进规格表。</span></p><p>离焦已经在焦深课里作为二次径向相位出现，它正是展开里的一项（Fringe 约定下常与 \\(Z_4\\) 对应）。本课要的是其余项：像散、彗差、球差、三叶……以及它们随视场怎么变。</p><h3 id="约定必须声明" tabindex="-1">约定必须声明 <a class="header-anchor" href="#约定必须声明" aria-label="Permalink to &quot;约定必须声明&quot;">​</a></h3><p>光刻与干涉仪常用 Fringe Zernike（Zygo 一类排序），与 Noll 索引同名不同号。球差、彗差的编号对不上表，系数全部错位。报 \\(c_j\\) 必须写哪一套。Malacara 把计量端的读法写清楚；本课不背诵全表，只要求后课引用系数时带约定。</p><p><span class="marginnote">Zernike 在单位圆上正交，加权是面积元 \\(\\rho\\,d\\rho\\,d\\phi\\)。光瞳若有中心遮拦或非圆，严格正交基要另选；产线仍常用 Zernike 当工程语言，残差另报。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把干涉仪或镜头出厂波前投到投影光瞳坐标（已按 \\(\\mathrm{NA}\\) 归一），拟合 \\(c_j\\)。低阶：倾斜（远心课的主光线斜率）、离焦、像散（两正交焦线）、彗差（视场随孔径的不对称）、球差（边缘带焦点相对近轴移动）。高阶项吃对比与通过焦点的 CD 不对称，对密图形的 NILS 更狠。</p><p><span class="marginnote">名字即直觉：彗差（coma）把一个点拖成带尾巴的彗星状光斑，越偏离视场中心尾巴越长；像散（astigmatism）让水平与垂直两个方向的焦点落在不同位置，一个点在两处各拉成一条正交焦线。线端圆角、左右 NILS 不对称，常是这两位干的好事。</span></p><p>场相关：每个视场点（扫描狭缝上的位置）可以有自己的系数向量。扫描方向再做时间平均。因此「本台镜头的彗差」必须声明是狭缝中心还是边缘。TCC 对每个场点可以不同，OPC 若用单一核，等于忽略这根向量。</p><h3 id="偏振通道共用几何相位-再乘矢量" tabindex="-1">偏振通道共用几何相位，再乘矢量 <a class="header-anchor" href="#偏振通道共用几何相位-再乘矢量" aria-label="Permalink to &quot;偏振通道共用几何相位，再乘矢量&quot;">​</a></h3><p>同一套 \\(c_j\\) 乘在 TE 与 TM 通道上，再叠加上一课的点积损失。像散让两个取向的 Bossung 错开；彗差让左右边 NILS 不对称，线变「一边陡一边缓」。机制是相位，不是又一种偏振。</p><p><span class="marginnote">热致波前随曝光负荷变。计量在冷态做的 Zernike 表，不等于扫描时的表。控制上这是镜头加热补偿，不是改定义。</span></p>',19)),(r(),o(B,null,{default:e(()=>[l(E,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%85%89%E7%9E%B3%E7%9B%B8%E4%BD%8D%20W%22%5D%20--%3E%20Z%5B%22Zernike%20%E7%B3%BB%E6%95%B0%20cj%22%5D%0A%20%20Z%20--%3E%20P%5B%22%E5%A4%8D%E5%85%89%E7%9E%B3%20P%22%5D%0A%20%20P%20--%3E%20TCC%5B%22TCC%20%2F%20%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20Z%20--%3E%20FLD%5B%22%E5%9C%BA%E7%82%B9%E5%90%91%E9%87%8F%22%5D%0A%20%20FLD%20--%3E%20OV%5B%22%E5%A5%97%E5%88%BB%20%2F%20%E5%B7%A6%E5%8F%B3%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("h2",{id:"机制",tabindex:"-1"},[i("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=n("p",null,"相位在光瞳上乘场，等于在像面与一个复衍射核卷积。离焦拉长核；像散让核变椭圆；彗差让核带尾巴，线端和套刻标记最敏感。频率上，高阶径向项对光瞳边缘加权重，而截止附近的级正走边缘，所以密图形先付像差税。",-1)),(r(),o(B,null,{default:e(()=>[l(E,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22%E4%BD%8E%E9%98%B6%E5%83%8F%E5%B7%AE%22%5D%20--%3E%20DF%5B%22%E7%A6%BB%E7%84%A6%22%5D%0A%20%20AB%20--%3E%20AS%5B%22%E5%83%8F%E6%95%A3%22%5D%0A%20%20AB%20--%3E%20CO%5B%22%E5%BD%97%E5%B7%AE%22%5D%0A%20%20AB%20--%3E%20SA%5B%22%E7%90%83%E5%B7%AE%22%5D%0A%20%20DF%20--%3E%20E1%5B%22%E8%A1%8D%E5%B0%84%E6%A0%B8%E6%8B%89%E9%95%BF%EF%BC%8C%E7%84%A6%E6%B7%B1%E5%8F%98%E8%96%84%22%5D%0A%20%20AS%20--%3E%20E2%5B%22%E6%A0%B8%E5%8F%98%E6%A4%AD%E5%9C%86%EF%BC%8C%E4%B8%A4%E5%8F%96%E5%90%91%20Bossung%20%E9%94%99%E5%BC%80%22%5D%0A%20%20CO%20--%3E%20E3%5B%22%E6%A0%B8%E5%B8%A6%E5%B0%BE%E5%B7%B4%EF%BC%8C%E7%BA%BF%E7%AB%AF%E4%B8%8E%E5%A5%97%E5%88%BB%E6%A0%87%E8%AE%B0%E6%9C%80%E7%97%9B%22%5D%0A%20%20SA%20--%3E%20E4%5B%22%E8%BE%B9%E7%BC%98%E4%B8%8E%E8%BF%91%E8%BD%B4%E7%84%A6%E7%82%B9%E9%94%99%E4%BD%8D%EF%BC%8C%E5%85%A8%E5%9C%BA%E5%AF%B9%E6%AF%94%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p>补偿：扫描机用镜头操纵（波长微调、透镜加热、可变形镜一类，视机台公开架构而定）去抵低阶项。本课不把补偿清单写成产品目录；只承认系数是可驱动的控制量。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到像差，默认是 Zernike（或等价正交基）系数，带约定与场点。\\(P\\) 的相位进 TCC，因而进 NILS 与 Bossung。色差课把 \\(c_j\\) 变成 \\(\\lambda\\) 的函数，本课先当单色。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Zernike 展开不包含杂散光、不包含多层膜散射。EUV 反射镜同样用波前系数说话，基底仍是圆（或 High-NA 变形光瞳要另写）。本课禁止编造未公开的 RMS 毫波数表；教科书与出厂计量原理已经够用。也不要把「Zernike 拟合残差小」写成成像已经理想：截断阶数之外的高频波前照样吃对比。</p><p><span class="marginnote">常见误区：以为 Zernike 编号全球统一。Fringe 与 Noll 两套约定同名不同号——同一个编号，在 Fringe 里可能是球差，在 Noll 里对上的是三叶。拿到任何一列 \\(c_j\\)，先问「哪套约定、怎么归一化」，再谈数值，否则彗差读成球差都不奇怪。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光瞳相位在圆域上按 Zernike 展开；报系数必须声明 Fringe 或 Noll。</li><li>离焦是其中一项；像散、彗差、球差改核的形状与对称。</li><li>系数随场点变；TCC 可以场相关。</li><li>同一套相位乘在 TE/TM 通道上，与矢量点积相乘。</li><li>单色系数下一课要对带宽积分。</li><li>出处：Zernike 圆多项式；Malacara, <em>Optical Shop Testing</em>；成像核见 Born &amp; Wolf / Mack。</li></ul>',8))])}const f=s(h,[["render",d]]);export{u as __pageData,f as default};
